-- 2225 🏋️ Exercises from the book "the-football-philosophy-in-shadows-of-marcelo-bielsa" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'the-football-philosophy-in-shadows-of-marcelo-bielsa');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('4v2 directional rondo, bottom to top', 'rondo', 'overload', 'in_possession', 140, 141, 'Section One 1.1: Four vs. Two Principles (Progression 0)', 'Bielsa-inspired (Jed Davies)', 'Learn to move two defenders with short and sideways passes so the ball can be split from the deepest player to the player at the far side.', 'Square of 8x8 to 12x12 yards (can be a rectangle) with four attackers on the sides and two defenders inside; the side holding the ball is the bottom, the opposite side is the top.', 'Attackers try to get the ball from the bottom player to the top player as often as possible, passing round the defenders only when the split pass is not on. Defenders sit on different lines to cut out the through pass and block passes up the sides.', 'When a defender wins it, the loser swaps in (some coaches also swap the player who gave the previous pass); swaps happen instantly and the new defender picks up the bib. Coach keeps a constant supply of balls.', 'Touch limits (one touch, two touch, or a touch cycle), a two-touch minimum to play under pressure, timed 45-second bouts scoring points for line-breaking passes or bottom-to-top moves.', 'Open hips towards the next pass, receive across the body, weight of pass for the receiver''s touch, deceptive movement and double movements before receiving.', '4v2', 6, 6, '8x8 to 12x12 yards', 11.0, 11.0, NULL, false, false, true, NULL, 10),
  ('Up-and-through rondo across two squares', 'rondo', 'overload', 'in_possession', 142, 143, 'Section One 1.2: Up and Through Rondo (no ''back'') (Progression 1)', 'Bielsa-inspired (Jed Davies)', 'Use a central player to drag two defenders out of position and penetrate to the player at the top, then switch play into the next square.', 'Two 8x8 to 12x12 yard squares side by side with a disc line between them; 5v2 in the active square (four outside plus a central player), the dividing-line player acts as the top.', 'Once the ball reaches the top player he turns and plays into the next square; the two outside players race across and the target waits at the far end. The ball must reach the target before it can go back across the line; the dividing-line player becomes the central player and the central player takes the line.', 'Two defenders always where the ball is: on a switch the nearer defender races across and the other blocks the target. Defenders stay in until they win it three times or the coach changes them.', 'Add a second central defender on the end lines (balance activity against standing time); change the size or shape of one box (wide and short, long and narrow).', 'Top player turns and passes in two touches; race across at full intensity; same receiving and body-shape details as 1.1.', '5v2 (plus target/next-square players)', 7, NULL, 'two 8x8 to 12x12 yard squares', 22.0, 11.0, NULL, false, false, true, NULL, 20),
  ('Up-back-through rondo with striker channel', 'rondo', 'overload', 'in_possession', 144, 145, 'Section One 1.3: Up-Back-Through Rondo (Progression 2)', 'Bielsa-inspired (Jed Davies)', 'Rehearse the up-back-through pattern: play into a dropping false 9, he sets it back, and a diagonal run from the winger receives the through pass.', 'Two 12x16 yard boxes with a 5-yard receiving channel between them (the space in front of the back line); cones 8-10 yards outside each box for the wingers. Square holds central defender, two fullbacks and central midfielder; a defender tracks the false 9.', 'Team plays up to the striker dropping into the channel, he sets back to a fullback or the midfielder, then both wingers run diagonally into the next square and the ball goes through to one; the winger plays to the target at the end and the drill mirrors, wingers becoming fullbacks and fullbacks racing out to become wingers.', 'The defender behind the striker follows him into the channel but may not tackle. Movements done at full speed with about 6-12 seconds rest between sprints.', 'Defender varies whether he follows; striker must decide to turn or set back; add a defender on the channel''s first line to block passes; add extra centre-backs at the bottom or turn one defender into a second striker so two strikers rotate; target can play one pass across before the next centre-back plays forward.', 'Striker only drops when the pass is on, otherwise resets and stretches; set the ball back with one touch (head over ball, compact body); striker movements: check in then come, step out of the defender''s eye-line, or push off and slip diagonally.', 'about 8 attackers v 3 defenders (per diagram)', NULL, NULL, 'two 12x16 yard boxes plus 5-yard channel', 34.0, 11.0, NULL, false, false, true, NULL, 30),
  ('Up-back-through pattern to finish', 'combination', 'unopposed', 'in_possession', 146, 147, 'Section One 1.4: Up-Back-Through Technical Pattern Practice', 'Bielsa-inspired (Jed Davies)', 'Repeat the up-back-through combination between midfielder, striker and winger and finish with the first touch.', 'Mannequins as defenders, 10-16 yards apart vertically and 8-16 yards horizontally, in front of a goal with a keeper; central midfielder with balls, striker in front of a mannequin centre-back, winger on each side.', 'Midfielder pushes the ball out of his feet, head up; striker drops in front of the mannequin and sets back one touch to the midfielder, who has moved to the other side; midfielder plays through for the winger''s diagonal run behind the mannequin and the winger finishes first time.', 'Winger first drops to support and only runs once the set-back is played.', 'Remove the mannequin and use a live defender who follows (or not) the striker; striker then turns or combines with the winger towards goal.', 'Pass quality, supporting angles, timing of movement and weight of the through ball.', NULL, NULL, NULL, 'mannequins 10-16 yards apart', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('Up-back-through drill into winger 1v1', 'one_v_one', 'opposed', 'in_possession', 148, 149, 'Section One 1.5: Up-Back-Through Drill', 'Bielsa-inspired (Jed Davies)', 'Link the up-back-through pattern to a winger''s 1v1 attack and teach recognising the striker''s movement.', 'Two 16x10 yard rectangles with a mini goal at each end and a channel of at least 4 yards between them; poles 10-16 yards away, a cone 6-8 yards off the pitches as the striker''s marker, and cones about 5 yards behind each pitch for the wingers.', 'Midfielder plays through the poles; striker moves off his marker and sets back left or right, which decides which side''s 1v1 goes live. After the set-back the winger runs diagonally into the 1v1 and the bottom defender joins; players rotate stations (midfielder to winger, striker to midfielder, defender to striker, winger to defender).', 'Winger may only run once the ball is set back.', 'Defender at the far end races to touch a goal post to decide which pitch goes live (the other one); gates or balls on cones can replace mini goals; build repetition, then speed, then complexity.', 'Pass quality, winger reading the striker''s movement, then attacking and defending the 1v1.', NULL, NULL, NULL, 'two 16x10 yard rectangles, 4-yard channel', 14.6, 9.1, NULL, true, false, true, NULL, 50),
  ('Up-back-through phase of play, zoned midfield', 'phase_of_play', 'opposed', 'in_possession', 150, 150, 'Section One 1.6: Up-Back-Through Phase of Play', 'Bielsa-inspired (Jed Davies)', 'Find the up-back-through pattern in a live phase against a zoned midfield line and finish through the winger.', 'Age-appropriate pitch marked with discs or tape; mini goals with mannequin fullbacks about 12 yards in front, a 3-yard-deep channel about 12 yards in front of the mannequins; goals beyond halfway for the defending team to counter into.', 'Blue defending midfielders are locked in zones and slide sideways to block passes into the striker; attackers play up to the striker, he sets back to a central midfielder, who plays through to a winger to finish in a mini goal (ideally the winger furthest from the ball). When the ball goes wide the nearest blue midfielder may leave his zone.', 'Any white player may play up to the striker; wingers only from the dotted line, maximum two touches. If blue win it they leave their zones and attack the goal; if white win it back and make three passes, blue return to zones. Opposition centre-backs may be limited early on.', 'See following page (p151, outside range).', 'Body shape, pass quality, reading the moment and movement; keep the opposition midfield and back line picture clear throughout.', NULL, NULL, NULL, 'age-appropriate pitch', NULL, NULL, NULL, true, false, true, NULL, 60),
  ('Up-back-through zonal small-sided game', 'small_sided_game', 'opposed', 'in_possession', 152, 153, '1.7 Up-Back-Through Small Sided Game', NULL, 'Build out from the back and break the opposition midfield line using the up-back-through pattern.', 'About 45 x 30 yards split into three 15-yard thirds, corners coned off; players locked in zones: 2v1 in the first third incl. GK, 4v3 in the middle incl. a neutral, a lone striker v centre back and GK in the last third.', 'Team builds from its keeper through the middle third; a player may only leave his zone when released by an up-back-through (lay-off and pass beyond the line), and goals only come from the final third.', 'Zones fixed, no transition movement; score only from the final third; any player (winger, CM or neutral) can run through on the up-back-through.', 'Change numbers in the blocking midfield channel, restrict the defenders'' movement, or add strikers to make it easier or harder.', 'Spot the up-back-through moment; body shape, positioning, timing of the run, quality of the set-back; striker may turn and finish if he has room.', '2v1, 4v3+N, 1v1+GK by zone', NULL, NULL, '45 x 30 yards (thirds of 15 x 30)', 41.1, 27.4, NULL, true, true, true, NULL, 70),
  ('Out-in-out rondo add-on', 'rondo', 'opposed', 'in_possession', 154, 155, '2.1 Out-In-Out Rondo (Progression 3)', NULL, 'Add the out-in-out pattern (winger comes inside, sets out to an overlapping fullback) to the up-back-through rondo to switch to the far target.', 'Same grid as the earlier up-back-through rondo (session 1.3) with target players at each end, wingers and fullbacks in wide squares, defenders inside; poles in the central receiving channel guide the wingers.', 'Teams work the ball to the far target via up-back-through or out-in-out: winger darts in to at least the edge of the receiving space, gets the ball, fullback overlaps into the next square to take the out pass and becomes the new winger as the rondo mirrors. At the target end one horizontal pass between the two centre backs is needed before playing forwards.', 'Fullback may not pass straight to the winger; transfers only via the two languages; nobody waits in the central zone; play never stops.', 'By numbers: 10 players (one target per end, no third defender), 11, 12, 13 (as shown), 14 (extra defender on the first line of the receiving space), 15 (two strikers); a defender tracking the winger inside; points or timed rounds so defenders become attackers.', 'Use out-in-out only on the strong side, not to switch to a weak-side winger; if the fullback misses the cue the central receiver turns and keeps the ball; keep intensity high.', '10-15 players', 10, 15, NULL, NULL, NULL, NULL, false, false, true, NULL, 80),
  ('Out-in-out crossing pattern with mannequins', 'combination', 'unopposed', 'in_possession', 156, 157, '2.2 Out-In-Out Technical Pattern Practice', NULL, 'Rehearse the CM-winger-overlapping fullback out-in-out pattern finished with varied crosses.', 'Mannequins as a defensive block 8-10 yards apart, a pole for the opposing fullback, cones marking start spots for CM, winger and fullback; goal in front.', 'CM drives out and looks up; winger moves inside in front of the pole, receives and sets back inside; fullback overlaps, CM plays him through and he crosses.', NULL, 'Vary the delivery: early whip behind the line, disguised cut-back, driven at one height, whipped to near post, lofted deep, curled to the back post; add defenders in the box to practise clearing among soft mannequins or poles.', 'Compact, toes-up set-back with head over the ball; quality and type of through ball dictates the cross; control on arrival for the fullback.', '3 attackers (CM, W, FB) per rep', 3, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 90),
  ('Out-in-out drill into 1v1 finish', 'combination', 'passive', 'in_possession', 158, 159, '2.3 Out-In-Out Drill', NULL, 'Learn the technical parts of the out-in-out and finish with a 1v1 against a recovering defender.', 'CM and winger cones about 20-25 yards apart, fullback cone about 10 yards behind the winger''s, a mini-goal 12-15 yards beyond the winger cone.', 'CM pushes the ball out and looks up; winger sprints in, receives the out pass and plays back first time; fullback overlaps diagonally, CM plays the final out ball, and the fullback attacks the mini-goal while the winger turns and chases as a tracking defender.', 'Fullback must take at least one touch before finishing.', 'Increase distance to the mini-goal to demand more 1v1 skill, defender coming at an angle, add a cross after the fullback''s run, or have him dribble through gates.', 'Weight, spin, direction and timing of the CM''s passes; winger''s movement and first-time lay-off; aggressive overlap and shielding off the tracker.', '3 per rep (CM, W, FB)', 3, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 100),
  ('Out-in-out phase of play through midfield', 'phase_of_play', 'opposed', 'in_possession', 160, 161, '2.4 Out-In-Out Phase of Play', NULL, 'Back four plus holding midfielder play through (not via) a guarded central area to strikers and wingers, using up-back-through and out-in-out.', 'Three mini-goals at one end, a receiving area with a central zone in which two fixed defending midfielders block and one attacking mate supports; at least two strikers press the back five.', 'Back five break lines into the striker or winger; then go to goal by the striker turning, a winger not tracked inside, an up-back-through if the striker is tight, or an out-in-out with the fullback overlapping.', 'Blocking midfielders do not intercept the set-back at first; when defenders win it they may leave zones until the attackers regain and make three passes, then reset.', NULL, 'Pass into the striker first (turn or set back), out-in-out is an add-on; decision making and non-verbal communication of the five building players.', 'Back four + DM v 2 strikers + 2 blocking midfielders, plus attackers', NULL, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 110),
  ('Out-in-out zonal small-sided game', 'small_sided_game', 'opposed', 'in_possession', 162, 163, '2.5 Out-In-Out Small Sided Game', NULL, 'Put up-back-through and out-in-out into a game with transition rules between attacking and defending shape.', 'Pitch in three thirds plus wide channels; in attack CB+GK in the first third, both fullbacks, two CMs and a neutral in the middle, striker plus two wingers (wide channels) in the last.', 'Up-back-through is the main language; wingers may dart in for an out-in-out (receive and finish if not followed, or set out if followed) with fullbacks overlapping whenever the winger goes inside. On losing it, fullbacks drop to the first third and wingers to the middle third.', 'Wingers stay wide until triggered; three passes in the central third to settle shape before acting (optional).', 'With fewer players remove one wide area (winger, fullback and a defender) as a function-format game.', 'Decisions between the four scoring scenarios; turn-and-shoot vs set back; intensity in transition.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Weak-side fullback rondo progression', 'rondo', 'opposed', 'in_possession', 164, 165, '3.1 Weak-side Fullback Rondo (Progression 4)', NULL, 'Final add-on to the rondo series: switch play through a weak-side fullback run as well as UBT and OIO.', 'Identical to the out-in-out rondo (targets, wide squares, poles) with strong side and weak side stressed in the introduction.', 'When the ball goes from the strong side into a CM who can turn out, the weak-side winger sprints inside behind the poles and the weak-side fullback advances to receive; the winger then returns outside and the fullback becomes the other side''s fullback as the rondo mirrors.', 'Previous rondo rules apply; if the fullback does not go, CM takes another option or keeps the ball.', 'Passing rules to control transitions (e.g. keep it three passes before the opposition must drop); individual 1v1 challenges or private minimum-touch rules for development.', 'CM finds the ''diagonal pocket'' to turn out to the weak side; still praise UBT and OIO options.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 130),
  ('Weak-side fullback circulation pattern', 'passing_opposed', 'passive', 'in_possession', 166, 167, '3.2 Weak-side Fullback Technical Pattern Practice', NULL, 'Circulate fullback to fullback through the centre backs and find the weak-side fullback via the deep midfielder.', 'Full width of the pitch (low, medium or high platform); poles for opposition fullbacks, mannequins, cones bounding defenders'' side-to-side movement, target CBs at the far end.', 'Ball goes from one fullback across both centre backs (no skipping) to the other fullback, back into the near CB, then into the deep midfielder who looks to the weak side where the winger has darted in and the fullback overlaps to receive.', 'At least one full circulation before playing into the midfielder; two touches (receive, release); wingers and fullbacks rotate roles.', 'By numbers: 10 (remove second CBs and next-square defender), 11, 12, 13 (as shown), 14 (extra defender blocking through balls), 15 (defenders follow the wingers inside).', 'Fullbacks wide on the ball side, tuck in when far; CBs give angles and take first touch forward; DM open body, moves with the ball and into the diagonal pocket; vary pass weight and type.', '10-15 players', 10, 15, NULL, NULL, NULL, NULL, false, false, true, NULL, 140),
  ('Weak-side fullback drill into 1v1', 'combination', 'passive', 'in_possession', 168, 169, '3.3 Weak-side Fullback Drill / Technical Pattern Practice', NULL, 'Rehearse positioning and support angles for a weak-side fullback release ending in a 1v1.', 'Seven cones, one mannequin and two mini-goals; centre backs spaced as in a game, DM beside the mannequin.', 'A fullback plays into a centre back, who touches forward and finds the DM; DM plays out to the weak side as the winger sprints to the inside cone and the fullback overlaps; the ball goes to the fullback and he plays 1v1 against the winger, now defending. Next rep starts from the other fullback.', NULL, 'Repetition, then speed and intensity, then complexity.', 'CB first touch forward and head up; DM on the far side of the mannequin from the ball, open hips, dropping off to give the angle; winger''s sprint timed to the DM''s first touch.', 'LB, RB, LCB, RCB, DM, LW, RW', 7, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 150),
  ('Weak-side fullback phase of play', 'phase_of_play', 'opposed', 'in_possession', 170, 171, '3.4 Weak-side Fullback Phase of Play', NULL, 'Add the weak-side fullback run to the up-back-through phase of play, finishing with a cross into a 2v2.', 'Same as the up-back-through phase of play (session 1.6): zones with blocking midfielders, mannequin fullbacks, mini-goals/goal.', 'When the DM receives on the weak side of midfield from a CB and can turn out, the weak-side winger runs in behind the midfield line and the weak-side CB, acting as fullback, overlaps for the ball; he crosses first time after control while the winger joins the striker for a 2v2 in the box.', 'Blue team transition rules as in 1.6; fullback delivers on his first touch after control.', 'Winger may also be found in behind the midfield line, turns and makes a 2v2 with the striker v two defenders, five seconds to score.', 'Up-back-through first, weak-side option second; DM finds an alternative if the moment is missed; FON + C scanning (forward, opposite, near, communicate).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 160),
  ('Weak-side fullback zonal small-sided game', 'small_sided_game', 'opposed', 'in_possession', 172, 173, '3.5 Weak-side Fullback Small Sided Game', NULL, 'Play the zonal game with UBT, OIO and now weak-side fullback options and crossing choices.', 'As the out-in-out small-sided game: thirds plus wide channels, CB+GK, fullbacks/CMs/neutral, striker and wingers.', 'UBT first; wingers can dart in for an out-in-out; if a weak-side chance appears the winger goes inside and the fullback overlaps to receive and cross. Defensive fall-back rules as before.', 'Wingers stay in wide channels unless triggered; fullbacks and wingers drop into set thirds when defending.', 'Minimum passes required in the first two thirds before playing into the final third to manage transitions.', 'Use the weak-side winger if unmarked; fullback acts fast with a choice of crosses (behind the line, driven, cut-back, lofted deep, curled to back post, whipped near post); FON + C.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Overload-to-isolate twin rondo switch', 'rondo', 'opposed', 'in_possession', 174, 175, '4.1 Overload-to-Isolate Rondo: Type A', NULL, 'Draw defenders to one side then switch quickly to an isolated winger for a 1v1 or cross.', 'Two 8x8-yard rondo boxes either side of the 18-yard box (about 36 yards apart), a central area behind them, and two poles about 5 yards from the boxes.', 'Two 3v1 rondos run; on the coach''s signal one box splits (nearest player to centre becomes a CM, furthest goes wide as a winger). The other box feeds the CM, who switches to the winger; its three players head into the box for the cross while the defender from the split box runs round the pole to close the winger.', NULL, 'Trigger by coach''s call, number of passes or losing the ball (that team defends); a third rondo inside the box whose three become attackers and defender joins; vary the defender''s angle and the 1v1.', 'CM opens up and demands the ball; vary delivery to the winger; winger''s first touch out of feet with purpose; choose 1v1 or cross types; runners fill box spaces as a group.', 'Two 3v1 rondos', 8, NULL, '8 x 8 yards boxes, 36 yards apart', 7.3, 7.3, NULL, true, true, true, NULL, 180),
  ('Overload-to-isolate rondo with far target', 'rondo', 'opposed', 'in_possession', 176, 177, '4.2 Overload-to-Isolate Rondo: Type B', NULL, 'Escape an overloaded 3v2 and switch to a far-side target, ending in a 1v1 to a mini-goal.', 'Two possession boxes 8x8 to 12x12 yards at least 10 yards apart, two mini-goals about 10 yards beyond each box; a left CB and left CM provide support angles.', '3v1 rondo on one side; on the third pass a second defender joins (3v2) and the group must get out and across through a central supporter. The far box''s defender slides to block the pass, then presses the target after his first touch while the CB and CM join; mirrors left to right. After three switches the winger attacks the goal and the defender recovers.', 'Far defender may only move side to side until the target receives.', 'Number of switches before the 1v1 decided by players, defender reacts to the target''s choice.', 'Ways out of tight situations and across to the weak side.', NULL, NULL, NULL, '8 x 8 to 12 x 12 yards boxes', NULL, NULL, NULL, true, false, true, NULL, 190),
  ('Back-to-back rondo boxes with switch', 'rondo', 'opposed', 'in_possession', 178, 179, '4.3 Overload-to-Isolate Rondo: Type C', NULL, 'Find a way out when defenders are dragged across to your overload and switch to the far side.', 'Two rondo boxes back to back, at least 12x12 yards each; three neutrals (two end targets and a central midfielder), teams of five.', 'Ball stays in one box until four passes are made, then is switched; in possession, team takes the wide spots (two per side), on a turnover the other team plays to a neutral and swaps roles as they sprint in and out.', 'Minimum four passes before switching; all bar the far target in the ball''s box; defending side keeps one player sliding along the blocking line.', 'Players choose how many switches before the 1v1 action; defender reacts to the target''s decision.', 'Tempo, supporting angles, moving to find space, manipulating defenders; demand intensity, keep a supply of balls so transitions are instant.', '5v5+3', 13, NULL, 'two 12 x 12 yard boxes', 11.0, 22.0, NULL, false, false, true, NULL, 200),
  ('Overload-to-isolate phase of play', 'phase_of_play', 'opposed', 'in_possession', 180, 181, '4.4 Overload-to-Isolate Phase of Play', NULL, 'Play under pressure, overload one side and find the isolated player, or break the line with an up-back-through.', 'Full goal one end, three mini-goals the other, three vertical lanes and a defensive line that can only be crossed after a task.', 'Whites attack the big goal and work one side with four or five passes before switching, or go up-back-through; only then may they enter the final 18 yards. Blues counter to the mini-goals.', 'Line broken only via UBT or overload-to-isolate; goals only from inside the 18-yard box; if whites regain after losing it and make three passes, defenders must reset to their line.', 'Flexible numbers (e.g. drop the blocker and central white); minimum or maximum touch limits, individualised.', 'Draw defenders across with third-line passes and striker passes; runs into vacated space; positioning; FON + C scanning.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 210),
  ('Overload-to-isolate zonal small-sided game', 'small_sided_game', 'opposed', 'in_possession', 182, 183, '4.5 Overload-to-Isolate Small Sided Game', NULL, 'Use overload-to-isolate in a game context alongside up-back-through.', 'Thirds with the central third halved lengthways and two wide channels; first and final thirds hold striker, CB and GK; middle third four midfielders a side plus a neutral.', 'Midfield takes the ball to one side; teams score via striker turning, UBT to a marked striker, or overload-to-isolate releasing the weak-side winger into the final third, after which the defender on the split line may sprint back as a second defender.', 'Zones locked unless triggered; neutral and at least one CM in the ball''s half; defenders commit only three to one half and leave one winger on the split line until the switch.', 'Vary allowed languages and how deep the defence sits; allow switch-and-slice as the opposite response; add wall passes off the striker; minimum passes before switching to the weak-side winger.', 'Playing out of pressure: movement, pass types, manipulating defenders; FON + C.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Two games linked by 1v1 task corridor', 'small_sided_game', 'overload', 'in_possession', 184, 185, '4.6 Overload-to-Isolate Game + Competitive Technical Task or Exercise', NULL, 'Play in temporary overloads and underloads created by a 1v1 challenge between two small games.', 'Two pitches with mini-goals at each end, separated by a 8-10 yard channel (the task corridor) with gates; ball supply at both ends; two teams of seven numbered 1-7, ideally two coaches.', 'One pitch starts 6v6, the other 1v1. Coach calls a number; both numbered players race to the corridor for a 1v1 through gates; winner sprints into the other pitch at once, loser does a forfeit (e.g. 30 juggles) before entering, so one pitch has a short overload. New numbers keep moving players across.', NULL, 'Any competitive task with a winner and loser; pitch-specific challenges (team out of possession drops to own half, ball loser touches own crossbar); can be used for fitness.', 'Coach in the shadows, pull players aside individually; use overloads, protect the ball when underloaded, 1v1 skill.', '14 (two teams of 7)', 14, 14, NULL, NULL, NULL, NULL, true, false, true, NULL, 230),
  ('Under and over two-player rotation box', 'positional_game', 'opposed', 'in_possession', 186, 187, '5.1 Under and Over Rotation', NULL, 'Teach the linked rotation of two central players to get the ball from end to end.', '12x12-yard box split into four with flat discs; players at each end.', 'Ball must travel end to end via a player in the centre (never direct), then back; the two central players rotate: one high/one low, one left/one right, then checkmark movements and circular under-over and over-under rotations.', 'No direct pass end to end; a bounce back to the same end player means no forward play, so a rotation must follow.', 'Two players at either end incl. a switch between CBs with three midfielders 3v3; tilt the cross into an X for a midfield diamond.', 'Movement relationship between two players; individual double and triple movements to lose a marker; hips and shoulders open to play forward.', NULL, NULL, NULL, '12 x 12 yards in four squares', 11.0, 11.0, NULL, false, false, true, NULL, 240),
  ('Midfield rotation 3v3 game with back four', 'small_sided_game', 'opposed', 'in_possession', 188, 189, '5.2 Rotations in Midfield Small Sided Game 1', NULL, 'Midfield three rotate collectively to receive from the back four and create a shot.', '15x20 to 20x30-yard central area for a 3v3, a wide channel each side and a 5-yard channel behind each goal.', 'Centre backs circulate behind the goal, fullback to fullback via the CBs, trying to feed the 3v3; once midfield receives they play back or work a shot.', 'Back four stay outside the central space; no skipping players in circulation.', 'Run as 2v2 or 4v4 depending on the preferred formation; touch limits.', 'Back four''s supporting angles as the starting point; coach collective movement of the three, e.g. isolating a 2v2 and 1v1.', '3v3 + back four each', NULL, NULL, '15 x 20 to 20 x 30 yards', NULL, NULL, NULL, true, false, true, NULL, 250),
  ('Midfield rotation game through central box', 'small_sided_game', 'opposed', 'in_possession', 190, 191, '5.3 Rotations in Midfield Small Sided Game 2', NULL, 'Central midfield rotation to find space and play forward into strikers.', '30x30 to 44x40-yard pitch with halfway line and a central box of 15x12 to 20x16 yards; goals with keepers.', '4v3 including the keeper must pass through the midfield box before going to one of the strikers to shoot.', 'Players fixed to zones.', 'Allow striker-midfielder rotation in the box; let midfielders and fullbacks join once the striker has the ball, with a transition rule (e.g. three passes forces defenders back into shape).', 'Collective movement of the three to create space; recognise when to pass into a rotation from deeper players.', '4v3 incl. GK', NULL, NULL, '30 x 30 to 44 x 40 yards', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Rotations phase of play to end zone', 'phase_of_play', 'opposed', 'in_possession', 192, 193, '5.4 Rotations Phase of Play', NULL, 'Use positional rotations to create advanced area actions and play forwards.', 'Two wide channels and an end zone with four mini-goals; attackers start with wingers in each channel and a striker in the end zone.', 'Attackers rotate (fullback-winger, fullback-winger-CM, the midfield three, striker-CM, under-over, full or semi-full expansive rotations) to get into the end zone and score.', 'Always one attacker in each wide channel and one in the end zone; enter the end zone only by a wall pass off the striker or dribbling in from the centre, not from wide; score only from the end zone.', 'Repetition, intensity/speed, then complexity.', 'Rotations tied to formation; expansive rotation only when the DM drops between the CBs.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 270),
  ('Rondo 3v1', 'rondo', 'overload', 'in_possession', 194, 195, '6.1 Rondo 3v1', NULL, 'Support angles and manipulating one defender to open a longer pass.', '8x8-yard area, three attackers v one defender.', 'Three keep the ball from one; the defender who wins it swaps with the player who lost it immediately.', 'Loser of the ball takes the bib himself; one and two touch encouraged.', 'Vary touch limits: maximum, minimum or a pattern (one, two, one...).', 'Open body shape, good angles; first-line passes draw the defender to create the longer pass; varied receiving and fakes.', '3v1', 4, 4, '8 x 8 yards', 7.3, 7.3, NULL, false, false, false, NULL, 280),
  ('Four-square rondo 4v4+2', 'rondo', 'overload', 'in_possession', 196, 197, '6.2 Rondo 4v4+2 (2v1)', NULL, 'Find the spare man and isolate 2v1 overloads in small squares.', '12x12 yards split into four squares; two neutrals and 4v4 whose spots depend on possession.', 'Attackers keep the ball using the spare player to create 2v1s in a square.', 'Max two defenders per square; up to three attackers in a box only if both neutrals are there; touch and minimum-pass limits per space.', 'Touch limits (max, min, sequence) and a minimum number of passes in each space.', 'Recognise when the overload shrinks: 2v1 beats 3v2; spot overloads appearing and disappearing.', '4v4+2', 10, 10, '12 x 12 yards', 11.0, 11.0, NULL, false, false, false, NULL, 290),
  ('Directional rondo 3v3+2 with transition', 'rondo', 'overload', 'to_attack', 198, 199, '6.3 Rondo 3v3+2', NULL, 'Keep the ball and, on winning it, play to the spare neutral and transition fast.', 'About 8x12 yards, 3v3 with two neutrals on the sides (shown as directional positions).', 'Team keeps the ball; defenders who win it play out to a neutral and sprint out to take the attackers'' positions.', NULL, 'Include another central neutral if needed; touch limits.', 'Speed of transition; play to the open spare man away from pressure; body orientation, angles, distances, movement to support.', '3v3+2', 8, 8, '8 x 12 yards', 11.0, 7.3, NULL, false, false, true, NULL, 300),
  ('Directional rondo 4v4+3', 'rondo', 'overload', 'to_attack', 200, 200, '6.4 Rondo 4v4+3', NULL, 'Manipulate defenders to find 2v1 situations and transition to attack via a neutral.', 'At least 8x16 yards; 4v4 plus three neutrals who never change roles; attackers on the outside, defenders inside.', 'North-south directional rondo: on a win the defenders pass to a neutral and take up outside positions while the other team sprints in to win it back.', 'Neutrals do not transition.', 'Seen on p201: 4v4+4 adds a second central neutral; 5v5+3 adds a fifth central defender and a central attacker with the neutral.', 'Defenders intercept rather than tackle and work together; attackers manipulate defenders and find 2v1s.', '4v4+3', 11, 11, '8 x 16 yards minimum', 14.6, 7.3, NULL, false, false, true, NULL, 310),
  ('Directional rondo 6v6 plus 3 neutrals', 'rondo', 'overload', 'in_possession', 202, 203, '6.5 Rondo 6v6+3', 'Bielsa', 'Move defenders as a group with angles and rotation to find 2v1s that let the ball split the lines.', 'Box about 8x12 to 10x15 yards; six attackers around the outside (targets at each end, wingers and fullbacks on the sides), three neutrals and six defenders inside.', 'Attackers circulate north to south and back, using the inside neutrals to pass through the defenders. When defenders win it they give it to a neutral and switch quickly into attacking spots.', 'Directional end to end and back.', 'Scale the numbers: at 4v4+4 add a second neutral inside; at 5v5+3 add a fifth defender plus one attacker inside with the neutral.', 'Support angles, individual movement to find space, rotations, pass types that shift defenders.', '6v6+3', 15, 15, '8x12 to 10x15 yards', 11.0, 7.3, NULL, false, false, true, NULL, 320),
  ('Play through four midfielders to striker', 'positional_game', 'overload', 'in_possession', 204, 205, '6.6 Overloading Opposition Midfield Lines', 'Bielsa', 'Use a four-man midfield to pull opposing midfielders and get the ball through to the striker.', 'Two 8x8-yard boxes end to end (8x16) with four mini-goals about 6 yards back from the area; defenders at the base, two deep and two advanced midfielders inside (4 v 3 centrally), striker at the far end.', 'Defenders find one of the four midfielders and the ball goes up to the striker, who lays it back to a defender directly or around/through/over the middle. Defending team win it and shoot at any mini-goal.', '1 point each time the ball reaches the striker; 3 points for defenders scoring in a mini-goal. Midfielders keep two per box unless a rotation is triggered; defenders can move between boxes; after regaining, reset to a defender first.', 'Rotations: into a diamond, attacking midfielder swapping with striker, or a winger tucking inside to form the same shape.', 'How four midfielders drag the opposing midfield and open space further up; bonus points for passing through both boxes.', '4 midfielders v 3 plus defenders and striker', NULL, NULL, '8x16 yards (two 8x8 boxes)', 14.6, 7.3, NULL, true, false, true, NULL, 330),
  ('SSG: loser of ball runs a task', 'small_sided_game', 'opposed', 'to_attack', 206, 207, '6.7 Isolating and Identifying Overloads', 'Bielsa', 'Spot and exploit the temporary overload created when an opponent is out of the game.', 'Small-sided pitch with good length, goals at both ends, poles in each corner.', 'Normal game, but whoever loses the ball must sprint to the furthest corner and complete a task (e.g. weave the poles) before rejoining, leaving his team a player short.', 'Optional: the player only does the task if his team fails to win the ball back within 3 seconds.', 'The corner task can be any technical or physical work planned for off the field.', 'Recognise where the overload is and how best to use it for chances; take more risk in possession when overloaded.', NULL, NULL, NULL, 'small-sided pitch, longer than wide', NULL, NULL, NULL, true, true, true, NULL, 340),
  ('Bielsa 1v1 on the line: crossing', 'one_v_one', 'opposed', 'in_possession', 208, 209, '7.1 One vs One Bielsa (Crossing)', 'Bielsa (also Berizzo, Tim Lees)', 'Win the wide 1v1 just enough to deliver a cross while the defender tries to block.', 'A second line about 1 yard outside the edge of the 18-yard box; defender works on the box line, attacker on the new line.', 'Attacker uses changes of pace with the ball to buy half a yard and cross; the defender shadows along his line to block the cross.', 'Both must stay close to their own line and may not cross it.', 'Ask for set cross types (whipped, driven, chipped, cutback); add targets such as goals or defenders who must clear.', 'Acceleration and deceleration with the ball; use both feet; defender watches the ball and never turns his back (fake crosses).', '1v1', 2, NULL, 'edge of 18-yard box', NULL, NULL, NULL, false, false, true, NULL, 350),
  ('Bielsa 1v1 on the line: shooting', 'one_v_one', 'opposed', 'in_possession', 210, 211, '7.2 One vs One Bielsa (Shooting)', 'Bielsa', 'Create a shooting chance from a tight 1v1 at the edge of the box.', 'Same two lines: the 18-yard line and a second line 1 yard outside it; goal beyond.', 'Same rules as the crossing version, but the attacker hunts a shot and the defender blocks it.', 'Stay on your own line.', 'Mannequin or real goalkeeper in different positions; ask for chip, placed, power, curled or dipped finishes; start by receiving a pass instead of from standing.', 'Sole-of-foot work, varied turns and fakes; explosive action.', '1v1 (+GK optional)', 2, NULL, 'edge of 18-yard box', NULL, NULL, NULL, true, false, true, NULL, 360),
  ('Protect the ball 3v2 with spare man', 'one_v_one', 'opposed', 'in_possession', 212, 213, '7.3 Protecting The Ball 3 vs 2', 'Pepijn Lijnders (FC Porto)', 'Get comfortable keeping the ball under pressure using 1v1 skills.', 'Space about 10x10 yards; two pairs duelling plus one spare player shared by both.', 'Each player must take a minimum number of touches or skill moves before using the spare man; since the spare man can''t serve both at once players often hold it longer.', 'Minimum touches or skills before releasing to the spare man.', 'Bigger area with more random defenders and receiving scenarios.', 'Shield and escape: Cruyff turn, U-turn, V-drag behind standing leg, Maradona turn, step-overs, sole rolls.', '3v2 (2 pairs + spare)', 5, 5, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 370),
  ('Receive with defender behind, gates', 'one_v_one', 'opposed', 'in_possession', 214, 215, '7.4 Receiving The Ball: Defender Behind 1', 'Tim Lees', 'Receive with a presser arriving from behind and beat him to dribble out.', 'Area 15-18 yards long by about 10 wide; pole at the start, mannequin, three cones, a gate each side and an end zone; five players for a continuous rotation.', 'Bottom player pushes the ball past the pole and passes to a receiver who comes off the mannequin; a defender sprints from the top to arrive on his first touch. Receiver has five seconds to dribble through a side gate or into the end zone. Players rotate: passer becomes receiver, receiver joins the queue to press, presser becomes next passer.', '5 seconds; 2 points end zone, 1 point side gate.', 'Move the defender''s start cone or add a cone he must round to change timing and angle.', 'Receive on the far foot, turn or no-touch turn depending on the press; defender comes fast, slows, side-on, low; attacker reads flaws in the approach.', '5', 3, 5, '15-18 x 10 yards', 15.0, 9.1, NULL, false, false, true, NULL, 380),
  ('End-to-end 1v1 to targets plus joiner', 'one_v_one', 'opposed', 'in_possession', 216, 217, '7.5 Receiving The Ball: Defender Behind 2', 'Bielsa', 'Receive with a defender behind and beat him or use a supporting runner to reach the target.', 'About 6x12 yards with a 3-yard rectangle at each end; a target player at each end, 1v1 in the middle, fifth player waiting in an end box; five players.', 'Ball goes into the middle receiver, who tries to play it to the far target while the defender tries to win it and play to either end (then roles swap). After the receiver''s second touch the fifth player can join to make it 2v1; whoever does not play into the target runs to that target, plays a wall pass and swaps with him.', 'Fifth player enters only after the receiver''s second touch.', 'Vary distance and type of the first pass (up to 20 yards); timed bouts where targets stay fixed to remove complexity.', 'Receiver stretches the defender at first; defender stays goal-side then may go ball-side; constant flow of balls.', '5 (1v1 + 2 targets + joiner)', 5, 5, '6 x 12 yards plus 3-yard end boxes', 11.0, 5.5, NULL, false, false, true, NULL, 390),
  ('Break lines run into mannequin gap', 'passing_unopposed', 'unopposed', 'in_possession', 218, 219, '7.6 Receiving The Ball While Breaking Lines Drill Type A', 'Bielsa (Athletic Bilbao)', 'Automate receiving after a fast forward run between opposition lines.', 'Three mannequins as a line of opponents with cones for the pass and run about 10-15 yards apart.', 'Ball from the top is set back to a bottom player who plays first time into the gap between mannequins; a runner makes a fast run to receive between the lines, dribbles to the next cone and sets the ball back to repeat.', 'First-time forward pass.', NULL, 'High intensity and repetition at pace; timing of run and collective action.', '3+', 3, NULL, '10-15 yards between cones', 11.4, NULL, NULL, false, false, true, NULL, 400),
  ('Post-line diagonal sprint and receive', 'passing_unopposed', 'unopposed', 'in_possession', 220, 221, '7.7 Receiving The Ball While Breaking Lines Drill Type B', 'Bielsa', 'Repeat receiving on a forward run at full speed with explosive action and little rest.', 'At least five lines of posts, each line two posts about 12 yards apart, lines 8-10 yards apart; three players.', 'A passes into B sprinting diagonally across to the next line; B dribbles to the following line and sets back to C, who one-touches into A sprinting on; the cycle climbs line by line to the end.', 'All sprints at 100%.', 'Shape the run to a match picture: winger beyond the back line or central midfielder breaking lines.', 'Repetition of one idea at full speed; football-specific fitness.', '3', 3, 3, '5 lines of posts, 8-10 yards apart, 12 yards wide', 33.0, 11.0, NULL, false, false, true, NULL, 410),
  ('Post-line receive behind a passive marker', 'passing_opposed', 'passive', 'in_possession', 222, 223, '7.8 Receiving The Ball While Breaking Lines Drill Type C', 'Bielsa', 'Receive behind a marker after a forward run, then cope with new pressure arriving.', 'At least four lines of posts, 8-10 yards apart and 12 yards wide; four or more players (attackers A and reference defenders D).', 'A(a) passes to A(b) sprinting in behind his marker D(a), who only acts as a reference; as A(b) dribbles on, D(b) closes him without trying to win it. Players reposition one line higher and A(b) passes back to reset the sequence a line further up.', 'Defenders are references only; all runs at 100%.', 'Repetition, then intensity and speed, then complexity.', 'Demand intensity; receiving behind an opponent with fresh pressure coming.', '4+', 4, NULL, '4 lines of posts, 8-10 yards apart, 12 yards wide', 25.0, 11.0, NULL, false, false, true, NULL, 420),
  ('Draw the presser, run in behind', 'one_v_one', 'opposed', 'in_possession', 224, 225, '7.9 Receiving The Ball While Breaking Lines Drill Type D', 'Bielsa', 'Exploit a defender drawn out by a horizontal pass with a give-and-run in behind (2v1).', 'Two cones 10 yards apart, a third 5 yards up from their midpoint, mini-goal 5 yards behind that; three players (two blue, one red defender).', 'Blues pass square until the red commits fully to press one of them; that player plays back to his partner and runs forward to receive behind the defender, then attacks the mini-goal.', 'Defender must fully commit to the press, not half-step.', 'Repetition, intensity and speed, then complexity.', 'Square pass as a pressing trigger pulls a midfielder out of his slot; 2v1 theme.', '2v1', 3, 3, 'cones 10 yards apart, goal 10 yards up', 9.1, 9.1, NULL, true, false, true, NULL, 430),
  ('Receive and switch the angle 1v1', 'one_v_one', 'opposed', 'in_possession', 226, 227, '7.10 Receiving The Ball to Switch Angle of Attack Drill', 'Bielsa', 'Receive under pressure as a central midfielder and turn out to switch play.', 'Two 6x15-yard rectangles back to back with a 6x4-yard box across the centre; mini-goals at each end; at least six players, three per rectangle.', 'End player plays an angled pass into the central midfielder, who receives and plays out to the opposite side; a defender sprints out from his line to win it and stop the switch, and if he wins it he dribbles over the end line.', 'Midfielder and defender start on their lines; feed must be angled, not flat.', 'Better without goals and with two players at each end: 3 points for a full switch, 1 point for playing back; timed bouts with scores; coloured gates at each end, coach calls the colour to play through.', 'Check the shoulder often; receiving and turning skills (step-overs, fakes, turn types); set semi-opposed or opposed to suit.', '6+', 6, NULL, 'two 6x15-yard rectangles plus 6x4 central box', NULL, NULL, NULL, true, false, true, NULL, 440),
  ('Up-back-through finishing behind CBs', 'combination', 'unopposed', 'in_possession', 228, 229, '8.1 Finishing Scenario A. Behind CBs Drill 1', 'Bielsa (Athletic Bilbao 2012/13)', 'Finish from runs in behind the back line using up-back-through patterns.', 'Two set-ups 10 yards between markers: one with a mannequin as a fullback, two poles and a cone; one with a single mannequin, a wall and two poles; goals at the end.', 'Left: striker drops off taking his centre-back, midfielder plays through for a wide player running diagonally behind. Right: up-back-through with the midfielder''s pass over a wall (defenders stepping up) for a runner behind a pulled-out fullback.', 'Finish in one or two touches.', NULL, 'Weight of pass, body shape, support angles, timing and type of movement.', '3 per set-up', 3, NULL, '10 yards between mannequins and poles', NULL, NULL, NULL, true, false, true, NULL, 450),
  ('Wall pass round corner, spin in behind', 'combination', 'unopposed', 'in_possession', 230, 231, '8.2 Finishing Scenario A. Behind CBs Drill 2', 'Bielsa', 'Pull a defender out and finish in the space left behind the centre-backs.', 'Poles and mannequins outside the box; first pass 12-18 yards, shot from about 12-16 yards; goalkeeper.', 'Attacker shows towards the ball to drop into the pocket, the ball goes up to the striker who lays it around the corner, and the first attacker spins in behind to shoot.', NULL, 'Variant where the centre-back does not follow the striker, so the striker turns and finishes in front of the line.', 'Pass quality and change of tempo; first-time finish, near and far post, ways past the keeper.', '3 + GK', 3, NULL, 'edge of box, 12-18 yard passes', NULL, NULL, NULL, true, true, true, NULL, 460),
  ('Dummy through to striker, spin behind', 'combination', 'unopposed', 'in_possession', 232, 233, '8.3 Finishing Scenario A. Behind CBs Drill 3', 'Bielsa (Athletic Bilbao v PSG 2011)', 'Use a midfielder''s forward run to draw a centre-back and release the striker behind.', 'Similar to drill 2: wide passer with mannequin, midfielder, striker, goalkeeper.', 'An angled pass looks meant for the forward-running midfielder, who dummies it through to the striker and spins into the space his pressing centre-back left, for a return and finish.', NULL, 'Variant where the centre-back does not follow, so the striker turns and finishes.', 'Disguise the dummy; carry over drill 2 points.', '3 + GK', 3, NULL, 'edge of box', NULL, NULL, NULL, true, true, true, NULL, 470),
  ('Zoned SSG: strikers behind the CBs', 'small_sided_game', 'opposed', 'in_possession', 234, 235, '8.4 Finishing Scenario A. Behind CBs Small Sided Game', 'Bielsa', 'Collectively use off-ball runs and wall passes to pull centre-backs out of their slots.', 'Directional small-sided game with a channel in the final third at one end and a coned area there to keep play central; goals and keepers.', 'Only the two strikers may enter the receiving area and final third until a trigger, such as a striker setting the ball back for an up-back-through, frees others to join.', 'Players locked in zones unless triggered.', 'Rotations between a striker and a central midfielder to provoke different pulls; scale repetitions, intensity, complexity.', 'Strikers combine with the wall pass and up-back-through language; unmarked strikers turn and shoot, so defenders must mark and cover.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 480),
  ('Get behind the fullback and cross', 'finishing', 'opposed', 'in_possession', 236, 237, '8.5 Finishing Scenario C. Behind FBs Opposed Drill', 'Bielsa', 'Winger gets behind the fullback with a one-two and picks the right delivery when pressed.', 'Mannequin at the corner of the box as the fullback, two poles for start positions, marked white area at the edge of the box; goalkeeper, defenders and attackers start in it.', 'Winger plays a one-two with the attacking midfielder to get behind the mannequin; once he receives, play is live and players leave their zones. If unpressed he finishes, but usually the holding midfielder or nearest centre-back comes out, opening space.', 'Players stay in zone until the ball is through to the winger.', 'Vary starting positions and who may go out to press the winger.', 'Read where space opened; crosses: whipped behind the line, driven across, disguised cutback, lofted to weak-side winger, curled back post, whipped front post.', NULL, NULL, NULL, 'around the 18-yard box', NULL, NULL, NULL, true, true, true, NULL, 490),
  ('Functional game: behind FBs zones', 'phase_of_play', 'overload', 'in_possession', 238, 239, '8.6 Finishing Scenario C. Behind FBs Functional Game', 'Bielsa', 'Assist from wide after getting behind the fullback and drawing a defender out of his slot.', 'Goals at both ends; cut lines from 8 yards outside the post to the box then angled to the centre circle, plus further angled divisions; fullback mannequin on the edge of the box.', 'White team attack through zones (GK, CB and dropping winger; striker, attacking mid and inside winger) against blue''s two forwards, fullback, two CBs, holding mid and keeper. Blue build out down the wing; once the winger passes the mannequin one defender may come out. White counter quickly into their 2v1 up front.', 'Final-zone attackers can''t leave their zone; mannequin ignored for offside; only one defender may press, and only after the winger passes the mannequin; central midfielder may drop to make 4v2 in build-up.', 'Change which players may enter which zones and on what conditions.', 'Find opened space when pressed; same six cross types as 8.5; defending side push up and hold a high line.', NULL, NULL, NULL, 'half to two-thirds pitch with zones', NULL, NULL, NULL, true, true, true, NULL, 500),
  ('Striker backpedal pattern v back four', 'combination', 'unopposed', 'in_possession', 240, 241, '8.7 Finishing Scenario D. In Front of FBs Technical Pattern Practice', 'Bielsa', 'Time the striker''s run behind a stepping-up centre-back when the winger has the ball facing forward.', 'Four mannequins as a back four set as if the winger has the ball, four cones as the opposition midfield line; goalkeeper.', 'Ball goes through two central midfielders out to the winger, then through to the striker once he has backpedalled toward the far centre-back and run in behind the near one who stepped across to cover.', NULL, 'Repetition, intensity and speed, complexity of tasks.', 'Striker''s backpedal and timing to exploit the gap behind the covering centre-back.', '4 + GK', 4, NULL, 'final third', NULL, NULL, NULL, true, true, true, NULL, 510),
  ('7v7 with positional match targets', 'small_sided_game', 'opposed', 'in_possession', 242, 243, 'Section 9: Match Targets 7 vs 7', NULL, 'Use per-position counting targets to steer a team toward the up-back-through language.', '7v7 match in a 1-2-3-1 shape, 48 minutes.', 'Normal game, each position has a count target: GK switches play about 24 times; fullbacks/centre-backs into striker''s feet 12 and into the central mid 12; central mid through balls and passes to striker''s feet about 20 each; wingers diagonal runs 18 and into striker 9; striker shows in the pocket 36 and chooses layoff vs turn.', 'Targets are per position, shared by players who split time there.', 'Coach adapts targets to the individuals and team.', 'Targets guide, not judge; missing one is usually a collective communication issue.', '7v7', 14, 14, NULL, NULL, NULL, 48.0, true, true, true, NULL, 520)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'the-football-philosophy-in-shadows-of-marcelo-bielsa') b;
INSERT INTO schema_migrations (filename) VALUES ('2225-exercises-book-the-football-philosophy-in-shadows-of-marcelo-bielsa.sql') ON CONFLICT DO NOTHING;
COMMIT;
